const config = {
  "previewFeatures": [],
  "clientVersion": "7.9.1",
  "engineVersion": "e922089b7d7502aff4249d5da3420f6fa55fc6ad",
  "activeProvider": "postgresql",
  "inlineSchema": "// CRM (second) Prisma client — ported from Ebright_OSC v1. Generated to its\n// own output dir and pointed at the live ebright_crm database via\n// CRM_DATABASE_URL (see prisma.crm.config.ts). Mirrors the task-manager\n// second-client pattern. Prisma 7: datasource url lives in the config file.\ngenerator client {\n  provider = \"prisma-client-js\"\n  output   = \"../../src/generated/crm-client\"\n}\n\ndatasource db {\n  provider = \"postgresql\"\n}\n\n// ============================================================\n// EXISTING HRMS MODELS (do not modify)\n// ============================================================\n\nmodel User {\n  id                 Int       @id @default(autoincrement())\n  email              String    @unique\n  passwordHash       String\n  role               String    @default(\"BRANCH_MANAGER\")\n  branchName         String?\n  createdAt          DateTime  @default(now())\n  name               String?\n  status             String    @default(\"ACTIVE\")\n  lastLoggedInAt     DateTime?\n  // Per-user dashboard access overrides on top of the role default in\n  // lib/dashboard-access.ts. Shape: { \"hrms.attendance\": \"DENIED\", \"crm\": \"ALLOWED\" }\n  // Null/empty = follow the role default for every key.\n  dashboardOverrides Json?\n\n  showcaseTasksAssigned       ShowcaseTask[]               @relation(\"ShowcaseTaskAssignee\")\n  showcaseTasksCreated        ShowcaseTask[]               @relation(\"ShowcaseTaskCreator\")\n  showcaseBudgetApproved      ShowcaseBudgetItem[]         @relation(\"ShowcaseBudgetApprover\")\n  showcaseAnnouncements       ShowcaseAnnouncement[]       @relation(\"ShowcaseAnnouncementAuthor\")\n  showcasePostMortems         ShowcasePostMortem[]         @relation(\"ShowcasePostMortemAuthor\")\n  showcaseOutreachLogs        ShowcaseSponsorOutreach[]    @relation(\"OutreachLogger\")\n  showcasePostMortemResponses ShowcasePostMortemResponse[] @relation(\"PostMortemResponder\")\n}\n\n// Tracks when a user's active sessions should be invalidated. Written by\n// /api/auth/change-password on a successful password update; consulted by\n// lib/nextauth.ts's jwt() callback and by middleware.ts on every page nav.\n//\n// Lives in the local `crm` schema (NOT on the User table) because crm.\"User\"\n// is an FDW view of ebright_hrfs.public.\"User\" and the FDW source doesn't\n// know about OSC's session lifecycle. Decoupling this row from the User\n// model means OSC owns its own revocation history end-to-end.\nmodel SessionRevocation {\n  email        String   @id\n  revokedAfter DateTime\n}\n\nmodel PasswordResetToken {\n  id        Int      @id @default(autoincrement())\n  tokenHash String   @unique\n  email     String\n  expiresAt DateTime\n  used      Boolean  @default(false)\n  createdAt DateTime @default(now())\n\n  @@index([email])\n}\n\n// Portal-wide announcement banner (e.g. maintenance countdown) shown at the\n// top of every page by app/components/AnnouncementBanner.tsx. Managed by\n// SUPER_ADMIN / ADMIN via /announcements. Only one row is active at a time —\n// POST /api/announcements deactivates the rest.\nmodel SystemAnnouncement {\n  id         Int       @id @default(autoincrement())\n  message    String\n  activateAt DateTime? // when the banner starts showing; null = immediately\n  startsAt   DateTime // when maintenance begins — the countdown target\n  endsAt     DateTime? // when to stop showing the banner; null = 30 min after startsAt\n  active     Boolean   @default(true)\n  createdBy  String?\n  createdAt  DateTime  @default(now())\n  updatedAt  DateTime  @updatedAt\n}\n\n// Per-role module × action (CRUD) permission matrix, managed by admins on\n// /account-management → Roles & Permissions. `permissions` is a JSON map of\n// { dashboardKey: Action[] } where keys come from DASHBOARD_TREE\n// (lib/dashboard-access.ts) and actions from lib/role-permissions.ts.\n// Roles with no row fall back to defaults derived from ROLE_ACCESS.\n//\n// Lives in ebright_hrfs public schema (via hrfsPrisma, lib/hrfs.ts), NOT the\n// crm database — same as ManpowerScheduleAttendance. Self-provisioned at\n// runtime by app/api/role-permissions/route.ts; only ever query it through\n// hrfsPrisma, never the default client.\nmodel RolePermission {\n  role        String   @id\n  permissions Json     @default(\"{}\")\n  updatedBy   String?\n  updatedAt   DateTime @default(now()) @updatedAt\n}\n\nmodel ManpowerSchedule {\n  id                 String   @id\n  branch             String\n  startDate          String\n  endDate            String\n  selections         Json\n  notes              Json\n  originalSelections Json\n  originalNotes      Json\n  status             String   @default(\"Finalized\")\n  submittedAt        DateTime @default(now())\n  originalAuthor     String\n}\n\n// BM's Present/Absent/Late attendance tick for a schedule week, keyed by\n// `${day}::${name}` inside the two JSON blobs. Deliberately a SEPARATE real\n// table, not columns on ManpowerSchedule — that model is a view backed by a\n// foreign table (FDW into ebright_hrfs; see the ON CONFLICT comment on\n// POST /api/schedules), so it can't take ALTER TABLE ADD COLUMN.\n//\n// Lives in ebright_hrfs itself (via hrfsPrisma, see lib/hrfs.ts), NOT in the\n// crm database this schema.prisma's datasource points at — same reasoning as\n// the BranchStaff writes in lib/hrfs.ts: a genuine table in ebright_hrfs\n// supports plain CREATE TABLE / INSERT ... ON CONFLICT, unlike the FDW view.\n// This model is declared here purely for documentation (the `db` datasource\n// above is crm, not hrfs) — it self-provisions at runtime (see\n// ensureAttendanceTable in app/api/schedules/route.ts) and is read/written\n// via raw SQL through hrfsPrisma, never the typed client generated from this\n// schema, so `prisma generate` / `prisma migrate` are not involved.\nmodel ManpowerScheduleAttendance {\n  scheduleId       String   @id\n  attendance       Json     @default(\"{}\")\n  attendanceLocked Json     @default(\"{}\")\n  updatedAt        DateTime @default(now())\n}\n\nmodel Employee {\n  id        Int      @id @default(autoincrement())\n  name      String\n  nickname  String?\n  branch    String\n  position  String?\n  createdAt DateTime @default(now())\n  CoachRate Decimal? @db.Decimal\n\n  @@unique([name, branch])\n}\n\nmodel BranchStaff {\n  id                 Int       @id @default(autoincrement())\n  name               String?\n  branch             String?\n  createdAt          DateTime  @default(now())\n  role               String?\n  nickname           String?\n  nric               String?\n  dob                String?\n  age                String?\n  gender             String?\n  nationality        String?\n  home_address       String?\n  phone              String?\n  email              String?\n  residential        String?\n  emergency_name     String?\n  emergency_phone    String?\n  emergency_relation String?\n  signed_date        String?\n  start_date         String?\n  employment_type    String?\n  status             String?\n  bank               String?\n  bank_name          String?\n  bank_account       String?\n  university         String?\n  department         String?\n  position           String?\n  location           String?\n  accessStatus       String?   @default(\"AUTHORIZED\")\n  contract           String?\n  employeeId         String?\n  endDate            String?\n  probation          String?\n  rate               String?\n  updatedAt          DateTime? @updatedAt\n  trainingStartDate  String?\n  trainingEndDate    String?\n  // Weekly schedule for the Staff Directory working-hours panel.\n  // Shape: { Mon: { start: \"09:00\", end: \"18:00\" } | null, ..., Sun: ... }\n  workingHours       Json?\n\n  @@map(\"BranchStaff\")\n}\n\n// Dated history of an employee's weekly working-hours schedule. Each row is a\n// version that takes effect on `effectiveFrom` and stays active until a later\n// version supersedes it. The attendance report judges each day's Late/Early by\n// the version active that day, so editing this/next week never rewrites past\n// weeks. BranchStaff.workingHours still holds the latest version as a cache for\n// the editor. Written/read via raw SQL (see staff-directory/actions.ts) so it\n// works before the generated client is refreshed.\nmodel BranchStaffSchedule {\n  id            Int      @id @default(autoincrement())\n  branchStaffId Int\n  effectiveFrom DateTime @db.Date\n  schedule      Json\n  createdAt     DateTime @default(now()) @db.Timestamptz(6)\n\n  @@unique([branchStaffId, effectiveFrom], map: \"uq_branchstaff_eff\")\n  @@index([branchStaffId, effectiveFrom], map: \"idx_bss_staff_eff\")\n  @@map(\"BranchStaffSchedule\")\n}\n\nmodel AttendanceLog {\n  id                Int      @id @default(autoincrement())\n  date              String\n  empNo             String\n  empName           String\n  clockInTime       String\n  clockInSerialNo   String\n  clockInEmailSent  Boolean  @default(false)\n  clockOutTime      String?\n  clockOutSerialNo  String?\n  clockOutEmailSent Boolean  @default(false)\n  scannerLocation   String?\n  createdAt         DateTime @default(now())\n  updatedAt         DateTime @updatedAt\n\n  @@unique([date, empNo])\n}\n\nmodel LeaveTransaction {\n  id                 Int       @id @default(autoincrement())\n  EmployeeCode       String?\n  LeaveTypeCode      String?\n  LeaveTransId       String?\n  ApplyDate          DateTime? @db.Timestamp(6)\n  ApplyReason        String?\n  ApplyStatus        String?\n  Attachment         String?\n  DayNo              Decimal?\n  HourNo             Decimal?\n  Days               String?\n  Source             String?\n  LeaveAdjustmentId  String?\n  LeaveDate          DateTime? @db.Date\n  FromTime           DateTime? @db.Time(6)\n  ToTime             DateTime? @db.Time(6)\n  IsHourly           Boolean?\n  IsAdjustment       Boolean?\n  LeaveCreditId      String?\n  created_at         DateTime? @default(now()) @db.Timestamp(6)\n  ActionRemark       String?\n  RequiredThirdParty Boolean?\n  WorkingHours       Int?\n\n  @@unique([LeaveTransId, LeaveDate], map: \"unique_leave_trans\")\n}\n\nmodel MedicalLeave {\n  id           Int      @id @default(autoincrement())\n  employeeCode String\n  name         String?\n  position     String?\n  dept         String?\n  branch       String?\n  leaveDate    DateTime @db.Date\n  reason       String?\n  status       String?\n  days         String?\n  leaveTransId String?  @unique\n  attachment   String?\n  createdAt    DateTime @default(now()) @db.Timestamp(6)\n}\n\n// ============================================================\n// SHARED AUDIT LOG (used by all Ebright modules)\n// ============================================================\n\nmodel core_audit_log {\n  id        String   @id @default(uuid())\n  tenantId  String?\n  userId    String?\n  userEmail String?\n  action    String\n  entity    String\n  entityId  String?\n  meta      Json?\n  ipAddress String?\n  userAgent String?\n  createdAt DateTime @default(now())\n\n  @@index([tenantId, entity, createdAt])\n  @@index([userId, createdAt])\n}\n\n// ============================================================\n// CRM MODULE — Better Auth tables\n// ============================================================\n\nmodel crm_auth_user {\n  id            String   @id @default(uuid())\n  email         String   @unique\n  emailVerified Boolean  @default(false)\n  name          String?\n  image         String?\n  createdAt     DateTime @default(now())\n  updatedAt     DateTime @updatedAt\n\n  sessions              crm_auth_session[]\n  accounts              crm_auth_account[]\n  userBranches          crm_user_branch[]\n  notifications         crm_notification[]\n  tasks                 crm_task[]\n  notes                 crm_note[]\n  calls                 crm_call[]\n  apiKeys               crm_api_key[]\n  assignedContacts      crm_contact[]        @relation(\"AssignedUser\")\n  assignedOpportunities crm_opportunity[]    @relation(\"AssignedUser\")\n  stageHistories        crm_stage_history[]\n  automationRuns        crm_automation_run[]\n  messages              crm_message[]\n  appointments          crm_appointment[]\n  leadTransfers         crm_lead_transfer[]\n\n  @@map(\"crm_auth_user\")\n}\n\nmodel crm_auth_session {\n  id        String   @id @default(uuid())\n  userId    String\n  token     String   @unique\n  expiresAt DateTime\n  ipAddress String?\n  userAgent String?\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  user crm_auth_user @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@map(\"crm_auth_session\")\n}\n\nmodel crm_auth_account {\n  id                    String    @id @default(uuid())\n  userId                String\n  accountId             String\n  providerId            String\n  accessToken           String?\n  refreshToken          String?\n  idToken               String?\n  accessTokenExpiresAt  DateTime?\n  refreshTokenExpiresAt DateTime?\n  scope                 String?\n  password              String?\n  createdAt             DateTime  @default(now())\n  updatedAt             DateTime  @updatedAt\n\n  user crm_auth_user @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@map(\"crm_auth_account\")\n}\n\nmodel crm_auth_verification {\n  id         String   @id @default(uuid())\n  identifier String\n  value      String\n  expiresAt  DateTime\n  createdAt  DateTime @default(now())\n  updatedAt  DateTime @updatedAt\n\n  @@map(\"crm_auth_verification\")\n}\n\n// ============================================================\n// CRM CORE MODELS\n// ============================================================\n\nmodel crm_tenant {\n  id        String   @id @default(uuid())\n  name      String\n  slug      String   @unique\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  branches crm_branch[]\n\n  @@map(\"crm_tenant\")\n}\n\nmodel crm_branch {\n  id              String   @id @default(uuid())\n  tenantId        String\n  name            String\n  /**\n   * Short branch code (e.g. \"AMP\", \"ST\", \"KD\"). Used by the dashboard\n   * bar chart + ticket module. Until the manage-branches feature went in\n   * this lived in a hard-coded map in leads-metrics; now it's a column\n   * so super-admins can add/rename branches without editing source.\n   */\n  code            String?\n  /**\n   * Region letter: 'A' | 'B' | 'C'. Drives the colour bucket on the\n   * super-admin dashboard bar chart. Nullable for branches outside the\n   * canonical regional grouping (e.g. the OD test branch, HR).\n   */\n  region          String?\n  address         String?\n  phone           String?\n  email           String?\n  operatingHours  Json?\n  timezone        String   @default(\"Asia/Kuala_Lumpur\")\n  branchManagerId String?\n  createdAt       DateTime @default(now())\n  updatedAt       DateTime @updatedAt\n\n  tenant           crm_tenant             @relation(fields: [tenantId], references: [id])\n  userBranches     crm_user_branch[]\n  pipelines        crm_pipeline[]\n  contacts         crm_contact[]\n  opportunities    crm_opportunity[]\n  tasks            crm_task[]\n  messages         crm_message[]\n  appointments     crm_appointment[]\n  automations      crm_automation[]\n  integrations     crm_integration[]\n  websiteForms     crm_website_form[]\n  emailSettings    crm_email_settings?\n  whatsappSettings crm_whatsapp_settings?\n  tags             crm_tag[]\n  customValues     crm_custom_value[]     @relation(\"BranchCustomValues\")\n  messageTemplates crm_message_template[]\n  transfersFrom    crm_lead_transfer[]    @relation(\"TransferFrom\")\n  transfersTo      crm_lead_transfer[]    @relation(\"TransferTo\")\n  whatsappLeads    crm_whatsapp_lead[]\n\n  @@index([tenantId])\n  @@map(\"crm_branch\")\n}\n\n/// Inbound WhatsApp interactions that a branch must process.\n///\n/// Each row mirrors one interaction from `ebrightleads_db.ws_leads` (anonymous\n/// \"1 message = 1 potential lead\" counts auto-inserted by the Meta WhatsApp\n/// pipeline) OR a manual entry added by a super admin. The CRM tracks the\n/// resolution state HERE rather than in ws_leads (which is owned by the\n/// external auto-system), keyed by `wsLeadId`. COMPLETED/DELETED rows act as\n/// tombstones so a re-sync never resurrects a cleared interaction.\n///\n/// Lifecycle: PENDING → (branch fills the WhatsApp form) COMPLETED, linking the\n/// `crm_contact` it created; or → (super admin) DELETED for \"just asking\"\n/// interactions. Only these two transitions clear a branch's red badge.\nmodel crm_whatsapp_lead {\n  id                String    @id @default(uuid())\n  tenantId          String\n  branchId          String\n  /// ws_leads.ws_lead_id for auto rows, or \"manual_<uuid>\" for super-admin adds.\n  wsLeadId          String\n  /// 'auto' (synced from ws_leads) | 'manual' (super-admin added).\n  source            String    @default(\"auto\")\n  /// 'PENDING' | 'COMPLETED' | 'DELETED'.\n  status            String    @default(\"PENDING\")\n  // Snapshot of the ws_leads row at sync time (ws_leads may change/disappear).\n  rawBranch         String?\n  locationKey       String?\n  fullName          String?\n  phone             String?\n  campaignName      String?\n  submittedAt       DateTime?\n  // Set when a branch completes the WhatsApp form.\n  contactId         String?\n  completedByUserId String?\n  completedAt       DateTime?\n  // Set when a super admin deletes the interaction.\n  deletedByUserId   String?\n  deletedAt         DateTime?\n  deleteReason      String?\n  createdAt         DateTime  @default(now())\n  updatedAt         DateTime  @updatedAt\n\n  branch crm_branch @relation(fields: [branchId], references: [id])\n\n  @@unique([tenantId, wsLeadId], name: \"uq_crm_whatsapp_lead_wsid\")\n  @@index([tenantId, branchId, status])\n  @@map(\"crm_whatsapp_lead\")\n}\n\nenum CrmUserRole {\n  SUPER_ADMIN\n  AGENCY_ADMIN\n  REGIONAL_MANAGER\n  BRANCH_MANAGER\n  BRANCH_STAFF\n}\n\nmodel crm_user_branch {\n  id        String      @id @default(uuid())\n  userId    String\n  branchId  String\n  tenantId  String\n  role      CrmUserRole\n  createdAt DateTime    @default(now())\n  updatedAt DateTime    @updatedAt\n\n  user   crm_auth_user @relation(fields: [userId], references: [id], onDelete: Cascade)\n  branch crm_branch    @relation(fields: [branchId], references: [id], onDelete: Cascade)\n\n  @@unique([userId, branchId])\n  @@index([tenantId])\n  @@map(\"crm_user_branch\")\n}\n\nmodel crm_pipeline {\n  id        String   @id @default(uuid())\n  tenantId  String\n  branchId  String\n  name      String\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  branch        crm_branch        @relation(fields: [branchId], references: [id])\n  stages        crm_stage[]\n  opportunities crm_opportunity[]\n\n  @@index([tenantId, branchId])\n  @@map(\"crm_pipeline\")\n}\n\nmodel crm_stage {\n  id               String   @id @default(uuid())\n  tenantId         String\n  pipelineId       String\n  name             String\n  shortCode        String\n  order            Int\n  color            String   @default(\"blue\")\n  stuckHoursYellow Int      @default(24)\n  stuckHoursRed    Int      @default(48)\n  createdAt        DateTime @default(now())\n  updatedAt        DateTime @updatedAt\n\n  pipeline           crm_pipeline        @relation(fields: [pipelineId], references: [id], onDelete: Cascade)\n  opportunities      crm_opportunity[]\n  stageHistoriesFrom crm_stage_history[] @relation(\"FromStage\")\n  stageHistoriesTo   crm_stage_history[] @relation(\"ToStage\")\n\n  @@index([tenantId, pipelineId, order])\n  @@map(\"crm_stage\")\n}\n\nenum TrialDay {\n  WED\n  THU\n  FRI\n  SAT\n  SUN\n}\n\nmodel crm_contact {\n  id                  String    @id @default(uuid())\n  tenantId            String\n  branchId            String\n  firstName           String\n  lastName            String?\n  email               String?\n  phone               String?\n  leadSourceId        String?\n  assignedUserId      String?\n  preferredBranchId   String?\n  preferredTrialDay   TrialDay?\n  enrolledPackage     String?\n  // For sibling-exploded imports (children in master_leads_base.children_details),\n  // contact.firstName/lastName holds the CHILD's name and parentFullName holds\n  // the parent's. Single-child / no-children imports leave parentFullName null\n  // so the card and the modal both show the same name.\n  parentFullName      String?\n  // Marketing campaign that produced this lead (from master_leads_base.campaign_name).\n  // Stored verbatim — display as written, no normalisation. Null = lead didn't\n  // come from a tracked campaign; UI renders \"-\" in that case.\n  campaignName        String?\n  // Free-text remarks the parent typed on the Wix / trial registration form.\n  // Stored directly on the contact (one per sibling) so the lead-detail card\n  // can show it without a separate note row. Null when none was entered.\n  remarks             String?\n  // Raw lead-source label as it arrived from the source system (e.g.\n  // \"roadshow\", \"trial-class-e form\") BEFORE normalizeSourceName() collapsed\n  // it into the canonical bucket on `leadSource`. Lets the lead-detail card\n  // show \"Others (roadshow)\" instead of a flat \"Others\". Null when the raw\n  // label matched the bucket or wasn't captured.\n  leadSourceDetail    String?\n  childName1          String?\n  childAge1           String?\n  childName2          String?\n  childAge2           String?\n  childName3          String?\n  childAge3           String?\n  childName4          String?\n  childAge4           String?\n  // Idempotency keys for inbound integration ingest. The pair points back at\n  // the source row in ebrightleads_db (e.g. \"meta_leads\" + \"6625556\"). The\n  // composite unique constraint makes it impossible to ingest the same lead\n  // twice — the LISTEN/NOTIFY worker and the polling backstop can race freely\n  // without producing duplicates.\n  externalSourceTable String?\n  externalSourceId    String?\n  deletedAt           DateTime?\n  createdAt           DateTime  @default(now())\n  updatedAt           DateTime  @updatedAt\n\n  branch         crm_branch           @relation(fields: [branchId], references: [id])\n  leadSource     crm_lead_source?     @relation(fields: [leadSourceId], references: [id])\n  assignedUser   crm_auth_user?       @relation(\"AssignedUser\", fields: [assignedUserId], references: [id])\n  contactTags    crm_contact_tag[]\n  notes          crm_note[]\n  tasks          crm_task[]\n  calls          crm_call[]\n  messages       crm_message[]\n  opportunities  crm_opportunity[]\n  appointments   crm_appointment[]\n  automationRuns crm_automation_run[]\n\n  @@unique([tenantId, externalSourceTable, externalSourceId], name: \"uq_crm_contact_external_source\")\n  @@index([tenantId, branchId])\n  @@index([tenantId, email])\n  @@index([tenantId, phone])\n  @@map(\"crm_contact\")\n}\n\nmodel crm_opportunity {\n  id                String    @id @default(uuid())\n  tenantId          String\n  branchId          String\n  contactId         String\n  pipelineId        String\n  stageId           String\n  value             Decimal   @default(0) @db.Decimal(12, 2)\n  assignedUserId    String?\n  lastStageChangeAt DateTime  @default(now())\n  deletedAt         DateTime?\n  createdAt         DateTime  @default(now())\n  updatedAt         DateTime  @updatedAt\n\n  branch        crm_branch          @relation(fields: [branchId], references: [id])\n  contact       crm_contact         @relation(fields: [contactId], references: [id])\n  pipeline      crm_pipeline        @relation(fields: [pipelineId], references: [id])\n  stage         crm_stage           @relation(fields: [stageId], references: [id])\n  assignedUser  crm_auth_user?      @relation(\"AssignedUser\", fields: [assignedUserId], references: [id])\n  stageHistory  crm_stage_history[]\n  leadTransfers crm_lead_transfer[]\n\n  @@index([tenantId, branchId, stageId])\n  @@index([tenantId, pipelineId])\n  // Kanban fetches a stage's cards filtered by createdAt and ordered by it —\n  // this covers the per-column query + ORDER BY without a sort step.\n  @@index([tenantId, stageId, createdAt])\n  @@map(\"crm_opportunity\")\n}\n\nmodel crm_stage_history {\n  id              String   @id @default(uuid())\n  tenantId        String\n  opportunityId   String\n  fromStageId     String?\n  toStageId       String\n  changedByUserId String?\n  note            String?\n  changedAt       DateTime @default(now())\n\n  opportunity   crm_opportunity @relation(fields: [opportunityId], references: [id], onDelete: Cascade)\n  fromStage     crm_stage?      @relation(\"FromStage\", fields: [fromStageId], references: [id])\n  toStage       crm_stage       @relation(\"ToStage\", fields: [toStageId], references: [id])\n  changedByUser crm_auth_user?  @relation(fields: [changedByUserId], references: [id])\n\n  @@index([tenantId, opportunityId])\n  @@map(\"crm_stage_history\")\n}\n\nmodel crm_lead_transfer {\n  id                  String   @id @default(uuid())\n  tenantId            String\n  opportunityId       String\n  fromBranchId        String\n  toBranchId          String\n  fromPipelineId      String\n  toPipelineId        String\n  fromStageId         String\n  toStageId           String\n  transferredByUserId String?\n  reason              String\n  transferredAt       DateTime @default(now())\n\n  opportunity   crm_opportunity @relation(fields: [opportunityId], references: [id], onDelete: Cascade)\n  fromBranch    crm_branch      @relation(\"TransferFrom\", fields: [fromBranchId], references: [id])\n  toBranch      crm_branch      @relation(\"TransferTo\", fields: [toBranchId], references: [id])\n  transferredBy crm_auth_user?  @relation(fields: [transferredByUserId], references: [id])\n\n  @@index([tenantId, opportunityId])\n  @@map(\"crm_lead_transfer\")\n}\n\nmodel crm_lead_source {\n  id        String   @id @default(uuid())\n  tenantId  String\n  name      String\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  contacts crm_contact[]\n\n  @@index([tenantId])\n  @@map(\"crm_lead_source\")\n}\n\nmodel crm_tag {\n  id        String   @id @default(uuid())\n  tenantId  String\n  branchId  String?\n  name      String\n  color     String   @default(\"#3b82f6\")\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  branch      crm_branch?       @relation(fields: [branchId], references: [id])\n  contactTags crm_contact_tag[]\n\n  @@index([tenantId])\n  @@map(\"crm_tag\")\n}\n\nmodel crm_contact_tag {\n  id        String   @id @default(uuid())\n  contactId String\n  tagId     String\n  createdAt DateTime @default(now())\n\n  contact crm_contact @relation(fields: [contactId], references: [id], onDelete: Cascade)\n  tag     crm_tag     @relation(fields: [tagId], references: [id], onDelete: Cascade)\n\n  @@unique([contactId, tagId])\n  @@map(\"crm_contact_tag\")\n}\n\nmodel crm_note {\n  id        String   @id @default(uuid())\n  tenantId  String\n  contactId String\n  userId    String?\n  body      String\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  contact crm_contact    @relation(fields: [contactId], references: [id], onDelete: Cascade)\n  user    crm_auth_user? @relation(fields: [userId], references: [id])\n\n  @@index([tenantId, contactId])\n  @@map(\"crm_note\")\n}\n\nmodel crm_task {\n  id             String    @id @default(uuid())\n  tenantId       String\n  branchId       String\n  contactId      String?\n  assignedUserId String?\n  title          String\n  dueAt          DateTime?\n  completedAt    DateTime?\n  createdAt      DateTime  @default(now())\n  updatedAt      DateTime  @updatedAt\n\n  branch       crm_branch?    @relation(fields: [branchId], references: [id])\n  contact      crm_contact?   @relation(fields: [contactId], references: [id])\n  assignedUser crm_auth_user? @relation(fields: [assignedUserId], references: [id])\n\n  @@index([tenantId, branchId])\n  @@index([tenantId, assignedUserId, dueAt])\n  @@map(\"crm_task\")\n}\n\nenum MessageChannel {\n  EMAIL\n  WHATSAPP\n  SMS\n}\n\nenum MessageDirection {\n  IN\n  OUT\n}\n\nmodel crm_message {\n  id                String           @id @default(uuid())\n  tenantId          String\n  branchId          String\n  contactId         String\n  userId            String?\n  channel           MessageChannel\n  direction         MessageDirection\n  body              String\n  subject           String?\n  status            String           @default(\"pending\")\n  providerMessageId String?\n  errorMessage      String?\n  createdAt         DateTime         @default(now())\n  updatedAt         DateTime         @updatedAt\n\n  branch  crm_branch     @relation(fields: [branchId], references: [id])\n  contact crm_contact    @relation(fields: [contactId], references: [id])\n  user    crm_auth_user? @relation(fields: [userId], references: [id])\n\n  @@index([tenantId, branchId, contactId])\n  @@map(\"crm_message\")\n}\n\nmodel crm_call {\n  id        String   @id @default(uuid())\n  tenantId  String\n  contactId String\n  userId    String?\n  outcome   String?\n  notes     String?\n  duration  Int?\n  createdAt DateTime @default(now())\n\n  contact crm_contact    @relation(fields: [contactId], references: [id], onDelete: Cascade)\n  user    crm_auth_user? @relation(fields: [userId], references: [id])\n\n  @@index([tenantId, contactId])\n  @@map(\"crm_call\")\n}\n\nmodel crm_message_template {\n  id        String         @id @default(uuid())\n  tenantId  String\n  branchId  String?\n  name      String\n  channel   MessageChannel\n  subject   String?\n  body      String\n  createdAt DateTime       @default(now())\n  updatedAt DateTime       @updatedAt\n\n  branch crm_branch? @relation(fields: [branchId], references: [id])\n\n  @@index([tenantId])\n  @@map(\"crm_message_template\")\n}\n\nenum CustomValueScope {\n  TENANT\n  BRANCH\n}\n\nmodel crm_custom_value {\n  id        String           @id @default(uuid())\n  tenantId  String\n  key       String\n  value     String\n  scope     CustomValueScope @default(TENANT)\n  scopeId   String?\n  createdAt DateTime         @default(now())\n  updatedAt DateTime         @updatedAt\n\n  branch crm_branch? @relation(\"BranchCustomValues\", fields: [scopeId], references: [id])\n\n  @@unique([tenantId, scope, scopeId, key])\n  @@index([tenantId])\n  @@map(\"crm_custom_value\")\n}\n\nenum AutomationTriggerType {\n  NEW_LEAD\n  STAGE_CHANGED\n  TAG_ADDED\n  TAG_REMOVED\n  TIME_IN_STAGE\n  SCHEDULED\n  FORM_SUBMITTED\n  INCOMING_MESSAGE\n  CUSTOM_FIELD_CHANGED\n  APPOINTMENT_BOOKED\n  CONTACT_REPLIED\n  NO_REPLY_AFTER\n  LEAD_TRANSFERRED\n  // Fires when a branch converts an inbound WhatsApp interaction (from the\n  // Opportunities WhatsApp inbox) into a real lead. Contact-centric, so every\n  // action node works the same as NEW_LEAD — but scoped to WhatsApp leads only.\n  WHATSAPP_LEAD\n}\n\nenum AutomationRunStatus {\n  PENDING\n  RUNNING\n  COMPLETED\n  FAILED\n  CANCELLED\n}\n\nmodel crm_automation {\n  id            String                @id @default(uuid())\n  tenantId      String\n  branchId      String?\n  name          String\n  triggerType   AutomationTriggerType\n  triggerConfig Json                  @default(\"{}\")\n  graph         Json                  @default(\"{}\")\n  enabled       Boolean               @default(false)\n  createdAt     DateTime              @default(now())\n  updatedAt     DateTime              @updatedAt\n\n  branch crm_branch?          @relation(fields: [branchId], references: [id])\n  runs   crm_automation_run[]\n\n  @@index([tenantId])\n  @@map(\"crm_automation\")\n}\n\nmodel crm_automation_run {\n  id                String              @id @default(uuid())\n  tenantId          String\n  automationId      String\n  contactId         String?\n  triggeredByUserId String?\n  status            AutomationRunStatus @default(PENDING)\n  startedAt         DateTime            @default(now())\n  completedAt       DateTime?\n  logs              Json                @default(\"[]\")\n\n  automation      crm_automation @relation(fields: [automationId], references: [id], onDelete: Cascade)\n  contact         crm_contact?   @relation(fields: [contactId], references: [id])\n  triggeredByUser crm_auth_user? @relation(fields: [triggeredByUserId], references: [id])\n\n  @@index([tenantId, automationId])\n  @@map(\"crm_automation_run\")\n}\n\nenum IntegrationType {\n  META\n  TIKTOK\n  WIX\n  GOOGLE_FORMS\n  GOOGLE_CALENDAR\n  OUTLOOK\n  WEBSITE_FORM\n}\n\nenum IntegrationStatus {\n  CONNECTED\n  DISCONNECTED\n  ERROR\n}\n\nmodel crm_integration {\n  id          String            @id @default(uuid())\n  tenantId    String\n  branchId    String\n  type        IntegrationType\n  credentials String?\n  status      IntegrationStatus @default(DISCONNECTED)\n  lastSyncAt  DateTime?\n  meta        Json?\n  createdAt   DateTime          @default(now())\n  updatedAt   DateTime          @updatedAt\n\n  branch      crm_branch                    @relation(fields: [branchId], references: [id])\n  oauthTokens crm_integration_oauth_token[]\n\n  @@unique([branchId, type])\n  @@index([tenantId])\n  @@map(\"crm_integration\")\n}\n\nmodel crm_integration_oauth_token {\n  id            String    @id @default(uuid())\n  integrationId String\n  accessToken   String\n  refreshToken  String?\n  expiresAt     DateTime?\n  scope         String?\n  createdAt     DateTime  @default(now())\n  updatedAt     DateTime  @updatedAt\n\n  integration crm_integration @relation(fields: [integrationId], references: [id], onDelete: Cascade)\n\n  @@map(\"crm_integration_oauth_token\")\n}\n\nmodel crm_website_form {\n  id               String   @id @default(uuid())\n  tenantId         String\n  branchId         String\n  name             String\n  schema           Json     @default(\"[]\")\n  publicSlug       String   @unique\n  submissionsCount Int      @default(0)\n  createdAt        DateTime @default(now())\n  updatedAt        DateTime @updatedAt\n\n  branch crm_branch @relation(fields: [branchId], references: [id])\n\n  @@index([tenantId])\n  @@map(\"crm_website_form\")\n}\n\nmodel crm_appointment {\n  id               String   @id @default(uuid())\n  tenantId         String\n  branchId         String\n  contactId        String\n  userId           String?\n  startAt          DateTime\n  endAt            DateTime\n  title            String?\n  notes            String?\n  calendarProvider String?\n  externalId       String?\n  createdAt        DateTime @default(now())\n  updatedAt        DateTime @updatedAt\n\n  branch  crm_branch     @relation(fields: [branchId], references: [id])\n  contact crm_contact    @relation(fields: [contactId], references: [id])\n  user    crm_auth_user? @relation(fields: [userId], references: [id])\n\n  @@index([tenantId, branchId])\n  // Each kanban card looks up its latest \"Trial Class\" appointment\n  // (WHERE contactId = ? AND title = ? ORDER BY startAt DESC LIMIT 1).\n  @@index([contactId, title, startAt])\n  @@map(\"crm_appointment\")\n}\n\nmodel crm_notification {\n  id        String    @id @default(uuid())\n  tenantId  String\n  userId    String\n  type      String\n  title     String\n  body      String\n  link      String?\n  readAt    DateTime?\n  createdAt DateTime  @default(now())\n\n  user crm_auth_user @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@index([tenantId, userId, readAt])\n  @@map(\"crm_notification\")\n}\n\nmodel crm_email_settings {\n  id                   String   @id @default(uuid())\n  tenantId             String\n  branchId             String   @unique\n  fromEmail            String\n  fromName             String\n  resendDomainVerified Boolean  @default(false)\n  createdAt            DateTime @default(now())\n  updatedAt            DateTime @updatedAt\n\n  branch crm_branch @relation(fields: [branchId], references: [id])\n\n  @@index([tenantId])\n  @@map(\"crm_email_settings\")\n}\n\nenum WhatsAppProvider {\n  META_CLOUD\n  TWILIO\n}\n\nmodel crm_whatsapp_settings {\n  id          String           @id @default(uuid())\n  tenantId    String\n  branchId    String           @unique\n  provider    WhatsAppProvider\n  credentials String?\n  createdAt   DateTime         @default(now())\n  updatedAt   DateTime         @updatedAt\n\n  branch crm_branch @relation(fields: [branchId], references: [id])\n\n  @@index([tenantId])\n  @@map(\"crm_whatsapp_settings\")\n}\n\nmodel crm_api_key {\n  id              String    @id @default(uuid())\n  tenantId        String\n  name            String\n  hashedKey       String    @unique\n  scopes          String[]  @default([])\n  lastUsedAt      DateTime?\n  createdByUserId String?\n  revokedAt       DateTime?\n  createdAt       DateTime  @default(now())\n  updatedAt       DateTime  @updatedAt\n\n  createdBy crm_auth_user? @relation(fields: [createdByUserId], references: [id])\n\n  @@index([tenantId])\n  @@map(\"crm_api_key\")\n}\n\nmodel crm_push_subscription {\n  id        String   @id @default(uuid())\n  userId    String\n  tenantId  String\n  endpoint  String\n  p256dh    String\n  auth      String\n  createdAt DateTime @default(now())\n\n  @@unique([userId, endpoint])\n  @@index([tenantId, userId])\n  @@map(\"crm_push_subscription\")\n}\n\n// ============================================================\n// TICKETING MODULE — tkt_* tables\n// ============================================================\n\nmodel tkt_platform {\n  id           String   @id @default(uuid())\n  tenant_id    String\n  name         String\n  slug         String\n  code         String // \"01\"-\"05\" used in ticket number generation\n  accent_color String   @default(\"#6b7280\")\n  created_at   DateTime @default(now())\n  updated_at   DateTime @updatedAt\n\n  user_platforms tkt_user_platform[]\n  tickets        tkt_ticket[]\n  counters       tkt_counter[]\n\n  @@unique([tenant_id, slug])\n  @@unique([tenant_id, name])\n  @@index([tenant_id])\n  @@map(\"tkt_platform\")\n}\n\nmodel tkt_branch {\n  id            String   @id @default(uuid())\n  tenant_id     String\n  name          String\n  code          String // e.g. \"AMP\"\n  branch_number String // \"01\"..\"26\" zero-padded, stable\n  created_at    DateTime @default(now())\n  updated_at    DateTime @updatedAt\n\n  user_branches tkt_user_branch[]\n  tickets       tkt_ticket[]\n  counters      tkt_counter[]\n\n  @@unique([tenant_id, branch_number])\n  @@unique([tenant_id, code])\n  @@index([tenant_id])\n  @@map(\"tkt_branch\")\n}\n\n// Ticket-specific user profile (extends crm_auth_user via user_id FK)\nmodel tkt_user_profile {\n  user_id             String   @id\n  tenant_id           String\n  role                String // \"super_admin\" | \"platform_admin\" | \"user\"\n  email_notifications Boolean  @default(true)\n  dark_theme          Boolean  @default(true)\n  activity_updates    Boolean  @default(true)\n  system_alerts       Boolean  @default(false)\n  audit_logs          Boolean  @default(false)\n  created_at          DateTime @default(now())\n  updated_at          DateTime @updatedAt\n\n  platforms tkt_user_platform[]\n  branches  tkt_user_branch[]\n  tickets   tkt_ticket[]\n\n  @@index([tenant_id])\n  @@index([tenant_id, role])\n  @@map(\"tkt_user_profile\")\n}\n\nmodel tkt_user_platform {\n  user_id     String\n  platform_id String\n\n  profile  tkt_user_profile @relation(fields: [user_id], references: [user_id], onDelete: Cascade)\n  platform tkt_platform     @relation(fields: [platform_id], references: [id], onDelete: Cascade)\n\n  @@id([user_id, platform_id])\n  @@map(\"tkt_user_platform\")\n}\n\nmodel tkt_user_branch {\n  user_id   String\n  branch_id String\n\n  profile tkt_user_profile @relation(fields: [user_id], references: [user_id], onDelete: Cascade)\n  branch  tkt_branch       @relation(fields: [branch_id], references: [id], onDelete: Cascade)\n\n  @@id([user_id, branch_id])\n  @@map(\"tkt_user_branch\")\n}\n\nmodel tkt_ticket {\n  id                String    @id @default(uuid())\n  ticket_number     String\n  tenant_id         String\n  branch_id         String\n  platform_id       String\n  user_id           String\n  issue_context     String\n  sub_type          String\n  fields            Json\n  status            String    @default(\"received\") // received | in_progress | complete | rejected\n  admin_remark      String?\n  rejection_reason  String?\n  assigned_admin_id String?\n  completed_at      DateTime?\n  visible_until     DateTime? // completed_at + 7 days; filtered server-side\n  created_at        DateTime  @default(now())\n  updated_at        DateTime  @updatedAt\n\n  platform    tkt_platform            @relation(fields: [platform_id], references: [id])\n  branch      tkt_branch              @relation(fields: [branch_id], references: [id])\n  submitter   tkt_user_profile        @relation(fields: [user_id], references: [user_id])\n  attachments tkt_ticket_attachment[]\n  events      tkt_ticket_event[]\n\n  @@unique([tenant_id, ticket_number])\n  @@index([tenant_id, platform_id, status])\n  @@index([tenant_id, branch_id])\n  @@index([tenant_id, user_id])\n  @@map(\"tkt_ticket\")\n}\n\nmodel tkt_ticket_attachment {\n  id         String   @id @default(uuid())\n  ticket_id  String\n  url        String\n  filename   String\n  size       Int\n  mime_type  String\n  created_at DateTime @default(now())\n\n  ticket tkt_ticket @relation(fields: [ticket_id], references: [id], onDelete: Cascade)\n\n  @@index([ticket_id])\n  @@map(\"tkt_ticket_attachment\")\n}\n\nmodel tkt_ticket_event {\n  id          String   @id @default(uuid())\n  ticket_id   String\n  event_type  String\n  description String?\n  meta        Json?\n  created_at  DateTime @default(now())\n\n  ticket tkt_ticket @relation(fields: [ticket_id], references: [id], onDelete: Cascade)\n\n  @@index([ticket_id])\n  @@map(\"tkt_ticket_event\")\n}\n\nmodel tkt_counter {\n  id            String   @id @default(uuid())\n  tenant_id     String\n  platform_id   String\n  branch_id     String?\n  counter_type  String // \"ticket\", \"daily\", etc.\n  year          Int\n  month         Int?\n  day           Int?\n  current_count Int      @default(0)\n  created_at    DateTime @default(now())\n  updated_at    DateTime @updatedAt\n\n  platform tkt_platform @relation(fields: [platform_id], references: [id])\n  branch   tkt_branch?  @relation(fields: [branch_id], references: [id])\n\n  @@unique([tenant_id, platform_id, branch_id, counter_type, year, month, day])\n  @@index([tenant_id])\n  @@map(\"tkt_counter\")\n}\n\n// ============================================================\n// BRANCH OPERATION DAYS — configurable per-branch operating day flags\n// ============================================================\n\nmodel BranchOperationDays {\n  id        Int      @id @default(autoincrement())\n  branch    String   @unique\n  wed       Boolean  @default(true)\n  thu       Boolean  @default(true)\n  fri       Boolean  @default(true)\n  sat       Boolean  @default(true)\n  sun       Boolean  @default(true)\n  updatedAt DateTime @updatedAt\n\n  @@map(\"branch_operation_days\")\n}\n\n// ============================================================\n// BRANCH QUOTA — per-branch daily staff quota targets for the\n// branch opening planning heatmap. Defaults to 5 when absent.\n// ============================================================\n\nmodel BranchQuota {\n  id        Int      @id @default(autoincrement())\n  branch    String   @unique // branch code e.g. \"RBY\"\n  wed       Int      @default(0)\n  thu       Int      @default(0)\n  fri       Int      @default(0)\n  sat       Int      @default(0)\n  sun       Int      @default(0)\n  updatedAt DateTime @updatedAt\n\n  @@map(\"branch_quota\")\n}\n\n// ============================================================\n// BRANCH WEEK SNAPSHOT — frozen weekly history of quota +\n// filled counts per branch for branch opening planning.\n// weekStart is the Wednesday that begins the Wed–Sun week.\n// The current week's rows are refreshed on page load and on\n// quota edits; past weeks are never written again.\n// ============================================================\n\nmodel BranchWeekSnapshot {\n  id        Int      @id @default(autoincrement())\n  branch    String // branch code e.g. \"RBY\"\n  weekStart DateTime @map(\"week_start\") @db.Date\n  wedQuota  Int      @default(0) @map(\"wed_quota\")\n  thuQuota  Int      @default(0) @map(\"thu_quota\")\n  friQuota  Int      @default(0) @map(\"fri_quota\")\n  satQuota  Int      @default(0) @map(\"sat_quota\")\n  sunQuota  Int      @default(0) @map(\"sun_quota\")\n  wedFilled Int      @default(0) @map(\"wed_filled\")\n  thuFilled Int      @default(0) @map(\"thu_filled\")\n  friFilled Int      @default(0) @map(\"fri_filled\")\n  satFilled Int      @default(0) @map(\"sat_filled\")\n  sunFilled Int      @default(0) @map(\"sun_filled\")\n  updatedAt DateTime @default(now()) @map(\"updated_at\")\n\n  @@unique([branch, weekStart])\n  @@map(\"branch_week_snapshot\")\n}\n\n// ============================================================\n// BURNLIST — weekly snapshots of expired+active students from\n// ebrightleads_db.studentrecords, with editable cta/remarks/done.\n// Each Wednesday a new BurnlistWeek is created and a row is\n// snapshotted per student. Entries store a frozen copy of\n// name/branch/expiry so historical weeks stay stable even when\n// the upstream studentrecords row changes.\n// ============================================================\n\nmodel BurnlistWeek {\n  id        String   @id @default(cuid())\n  weekKey   String   @unique // YYYY-MM-DD of the Wednesday, e.g. \"2026-05-20\"\n  createdAt DateTime @default(now())\n\n  entries BurnlistEntry[]\n\n  @@map(\"burnlist_week\")\n}\n\nmodel BurnlistEntry {\n  id     String       @id @default(cuid())\n  weekId String\n  week   BurnlistWeek @relation(fields: [weekId], references: [id], onDelete: Cascade)\n\n  // Snapshot fields — copied from studentrecords at snapshot time.\n  studentRecordId String\n  studentName     String\n  branch          String // raw branch code, e.g. \"ST\"\n  expiryDate      String // YYYY-MM-DD as Postgres held it\n\n  // Editable action fields. Blank on snapshot; filled in by BMs / user.\n  cta     String  @default(\"\") // \"\" | \"Extend\" | \"Archive\" | \"Renew\" | \"No Action\"\n  remarks String  @default(\"\")\n  done    Boolean @default(false)\n\n  updatedAt DateTime @updatedAt\n\n  @@unique([weekId, studentRecordId])\n  @@index([weekId])\n  @@map(\"burnlist_entry\")\n}\n\n// ============================================================\n// ANNUAL SHOWCASE MODULE — showcase_* tables\n// ============================================================\n\nenum ShowcaseEditionStatus {\n  DRAFT\n  REGISTRATION_OPEN\n  TEST_RUN\n  EVENT_ACTIVE\n  POST_EVENT\n  ARCHIVED\n}\n\nenum ShowcaseTaskStatus {\n  TODO\n  IN_PROGRESS\n  IN_REVIEW\n  DONE\n}\n\nenum ShowcaseTaskPriority {\n  LOW\n  MEDIUM\n  HIGH\n  URGENT\n}\n\nenum ShowcaseBudgetType {\n  REVENUE\n  EXPENSE\n}\n\nenum ShowcaseBudgetItemStatus {\n  PENDING\n  APPROVED\n  PAID\n  REJECTED\n}\n\nenum ShowcaseSponsorStatus {\n  PROSPECT\n  CONTACTED\n  NEGOTIATING\n  CONFIRMED\n  DECLINED\n  LEAD\n  MEETING\n  MOU_SIGNED\n  FULFILLED\n}\n\nmodel ShowcaseEdition {\n  id                     String                @id @default(cuid())\n  name                   String\n  theme                  String\n  status                 ShowcaseEditionStatus @default(DRAFT)\n  startDate              DateTime?\n  endDate                DateTime?\n  venueName              String?\n  venueAddress           String?\n  participantTarget      Int                   @default(0)\n  profitabilityTarget    Float                 @default(0)\n  registrationDeadline   DateTime?\n  testRunDate            DateTime?\n  currency               String                @default(\"MYR\")\n  isActive               Boolean               @default(false)\n  departmentLeads        Json?\n  goodieBagChecklist     Json?\n  logisticsData          Json?\n  sponsorPackages        Json?\n  photographerGuidelines Json?\n  pressCoverage          Json?\n  photoDistribution      Json?\n  scoringCriteria        Json?\n  stageChecklist         Json?\n  youthpreneurLayout     Json?\n  waitlistEnabled        Boolean               @default(false)\n  waitlistCount          Int                   @default(0)\n  createdAt              DateTime              @default(now())\n  updatedAt              DateTime              @updatedAt\n\n  members             ShowcaseMember[]\n  participants        ShowcaseParticipant[]\n  categories          ShowcaseCategory[]\n  feeWaves            ShowcaseFeeWave[]\n  tasks               ShowcaseTask[]\n  budgetItems         ShowcaseBudgetItem[]\n  sponsors            ShowcaseSponsor[]\n  announcements       ShowcaseAnnouncement[]\n  postMortems         ShowcasePostMortem[]\n  manpower            ShowcaseManpower[]\n  mediaPosts          ShowcaseMediaPost[]\n  postMortemResponses ShowcasePostMortemResponse[]\n  cueSheetBlocks      ShowcaseCueSheetBlock[]\n  scores              ShowcaseScore[]\n  youthpreneurBooths  ShowcaseYouthpreneurBooth[]\n  waitlist            ShowcaseWaitlist[]\n\n  @@map(\"showcase_edition\")\n}\n\nmodel ShowcaseMember {\n  id           String          @id @default(cuid())\n  editionId    String\n  edition      ShowcaseEdition @relation(fields: [editionId], references: [id], onDelete: Cascade)\n  email        String\n  name         String?\n  allowedUnits String[]        @default([])\n  invitedAt    DateTime        @default(now())\n\n  @@unique([editionId, email])\n  @@index([editionId])\n  @@map(\"showcase_member\")\n}\n\nmodel ShowcaseCategory {\n  id          String   @id @default(cuid())\n  editionId   String\n  name        String\n  description String?\n  maxTeamSize Int      @default(4)\n  createdAt   DateTime @default(now())\n\n  edition      ShowcaseEdition       @relation(fields: [editionId], references: [id], onDelete: Cascade)\n  participants ShowcaseParticipant[]\n\n  @@map(\"showcase_category\")\n}\n\nmodel ShowcaseFeeWave {\n  id        String   @id @default(cuid())\n  editionId String\n  name      String\n  amount    Float\n  deadline  DateTime\n  createdAt DateTime @default(now())\n\n  edition      ShowcaseEdition       @relation(fields: [editionId], references: [id], onDelete: Cascade)\n  participants ShowcaseParticipant[]\n\n  @@map(\"showcase_fee_wave\")\n}\n\nmodel ShowcaseParticipant {\n  id            String    @id @default(cuid())\n  editionId     String\n  categoryId    String?\n  feeWaveId     String?\n  fullName      String\n  email         String?\n  phone         String?\n  teamName      String?\n  paymentStatus String    @default(\"UNPAID\")\n  dateOfBirth   DateTime?\n  isEbrighter   Boolean   @default(false)\n  parentName    String?\n  parentEmail   String?\n  parentPhone   String?\n  orderNo       Int?\n  paymentLog    Json?\n  faStudentId   String?\n  emailSentAt   DateTime?\n  checkpoints   Json      @default(\"[]\")\n  registeredAt  DateTime  @default(now())\n  updatedAt     DateTime  @updatedAt\n\n  edition  ShowcaseEdition   @relation(fields: [editionId], references: [id], onDelete: Cascade)\n  category ShowcaseCategory? @relation(fields: [categoryId], references: [id])\n  feeWave  ShowcaseFeeWave?  @relation(fields: [feeWaveId], references: [id])\n  scores   ShowcaseScore[]\n\n  @@index([editionId])\n  @@map(\"showcase_participant\")\n}\n\nmodel ShowcaseTask {\n  id          String               @id @default(cuid())\n  editionId   String\n  unit        String\n  title       String\n  description String?\n  status      ShowcaseTaskStatus   @default(TODO)\n  priority    ShowcaseTaskPriority @default(MEDIUM)\n  assigneeId  Int?\n  createdById Int?\n  dueDate     DateTime?\n  createdAt   DateTime             @default(now())\n  updatedAt   DateTime             @updatedAt\n\n  edition   ShowcaseEdition @relation(fields: [editionId], references: [id], onDelete: Cascade)\n  assignee  User?           @relation(\"ShowcaseTaskAssignee\", fields: [assigneeId], references: [id])\n  createdBy User?           @relation(\"ShowcaseTaskCreator\", fields: [createdById], references: [id])\n\n  @@index([editionId, unit])\n  @@map(\"showcase_task\")\n}\n\nmodel ShowcaseBudgetItem {\n  id           String                   @id @default(cuid())\n  editionId    String\n  unit         String\n  type         ShowcaseBudgetType\n  description  String\n  amount       Float\n  status       ShowcaseBudgetItemStatus @default(PENDING)\n  approvedById Int?\n  approvedAt   DateTime?\n  createdAt    DateTime                 @default(now())\n  updatedAt    DateTime                 @updatedAt\n\n  edition    ShowcaseEdition @relation(fields: [editionId], references: [id], onDelete: Cascade)\n  approvedBy User?           @relation(\"ShowcaseBudgetApprover\", fields: [approvedById], references: [id])\n\n  @@index([editionId])\n  @@map(\"showcase_budget_item\")\n}\n\nmodel ShowcaseSponsor {\n  id             String                @id @default(cuid())\n  editionId      String\n  companyName    String\n  contactName    String?\n  contactEmail   String?\n  contactPhone   String?\n  packageType    String?\n  amount         Float                 @default(0)\n  pipelineStatus ShowcaseSponsorStatus @default(PROSPECT)\n  notes          String?\n  isVVIP         Boolean               @default(false)\n  createdAt      DateTime              @default(now())\n  updatedAt      DateTime              @updatedAt\n\n  edition     ShowcaseEdition           @relation(fields: [editionId], references: [id], onDelete: Cascade)\n  outreachLog ShowcaseSponsorOutreach[]\n\n  @@index([editionId])\n  @@map(\"showcase_sponsor\")\n}\n\nmodel ShowcaseAnnouncement {\n  id          String   @id @default(cuid())\n  editionId   String\n  title       String\n  body        String\n  targetUnits String[] @default([])\n  authorId    Int?\n  createdAt   DateTime @default(now())\n\n  edition ShowcaseEdition @relation(fields: [editionId], references: [id], onDelete: Cascade)\n  author  User?           @relation(\"ShowcaseAnnouncementAuthor\", fields: [authorId], references: [id])\n\n  @@index([editionId])\n  @@map(\"showcase_announcement\")\n}\n\nmodel ShowcasePostMortem {\n  id          String   @id @default(cuid())\n  editionId   String\n  unit        String\n  highlights  String?\n  lowlights   String?\n  suggestions String?\n  authorId    Int?\n  createdAt   DateTime @default(now())\n  updatedAt   DateTime @updatedAt\n\n  edition ShowcaseEdition @relation(fields: [editionId], references: [id], onDelete: Cascade)\n  author  User?           @relation(\"ShowcasePostMortemAuthor\", fields: [authorId], references: [id])\n\n  @@index([editionId])\n  @@map(\"showcase_post_mortem\")\n}\n\nmodel ShowcaseManpower {\n  id        String          @id @default(cuid())\n  editionId String\n  edition   ShowcaseEdition @relation(fields: [editionId], references: [id], onDelete: Cascade)\n  unit      String\n  type      String\n  name      String\n  role      String\n  phone     String?\n  email     String?\n  shift     String?\n  day       String?\n  status    String          @default(\"CONFIRMED\")\n  notes     String?\n  createdAt DateTime        @default(now())\n  updatedAt DateTime        @updatedAt\n\n  @@index([editionId, unit])\n  @@index([type])\n  @@map(\"showcase_manpower\")\n}\n\nmodel ShowcaseSponsorOutreach {\n  id           String          @id @default(cuid())\n  sponsorId    String\n  sponsor      ShowcaseSponsor @relation(fields: [sponsorId], references: [id], onDelete: Cascade)\n  type         String\n  date         DateTime\n  outcome      String?\n  followUpDate DateTime?\n  loggedById   Int?\n  loggedBy     User?           @relation(\"OutreachLogger\", fields: [loggedById], references: [id])\n  createdAt    DateTime        @default(now())\n\n  @@index([sponsorId])\n  @@map(\"showcase_sponsor_outreach\")\n}\n\nmodel ShowcaseMediaPost {\n  id          String          @id @default(cuid())\n  editionId   String\n  edition     ShowcaseEdition @relation(fields: [editionId], references: [id], onDelete: Cascade)\n  platform    String\n  caption     String?\n  mediaType   String\n  scheduledAt DateTime?\n  publishedAt DateTime?\n  status      String          @default(\"DRAFT\")\n  link        String?\n  notes       String?\n  createdAt   DateTime        @default(now())\n  updatedAt   DateTime        @updatedAt\n\n  @@index([editionId])\n  @@map(\"showcase_media_post\")\n}\n\nmodel ShowcasePostMortemResponse {\n  id              String          @id @default(cuid())\n  editionId       String\n  edition         ShowcaseEdition @relation(fields: [editionId], references: [id], onDelete: Cascade)\n  unit            String\n  submittedById   Int?\n  submittedBy     User?           @relation(\"PostMortemResponder\", fields: [submittedById], references: [id])\n  wentWell        String?\n  didNotGoWell    String?\n  improvements    String?\n  recommendations String?\n  rating          Int?\n  submittedAt     DateTime        @default(now())\n\n  @@unique([editionId, unit])\n  @@index([editionId])\n  @@map(\"showcase_post_mortem_response\")\n}\n\nmodel ShowcaseCueSheetBlock {\n  id           String          @id @default(cuid())\n  editionId    String\n  edition      ShowcaseEdition @relation(fields: [editionId], references: [id], onDelete: Cascade)\n  dayNumber    Int\n  order        Int\n  title        String\n  type         String\n  startTime    String\n  durationMins Int\n  pic          String?\n  status       String          @default(\"UPCOMING\")\n  notes        String?\n  createdAt    DateTime        @default(now())\n  updatedAt    DateTime        @updatedAt\n\n  @@index([editionId, dayNumber])\n  @@map(\"showcase_cue_sheet_block\")\n}\n\nmodel ShowcaseScore {\n  id             String              @id @default(cuid())\n  editionId      String\n  edition        ShowcaseEdition     @relation(fields: [editionId], references: [id], onDelete: Cascade)\n  participantId  String\n  participant    ShowcaseParticipant @relation(fields: [participantId], references: [id], onDelete: Cascade)\n  judgeName      String\n  criteriaScores Json\n  total          Float\n  locked         Boolean             @default(false)\n  submittedAt    DateTime            @default(now())\n\n  @@index([editionId])\n  @@index([participantId])\n  @@map(\"showcase_score\")\n}\n\nmodel ShowcaseYouthpreneurBooth {\n  id            String                        @id @default(cuid())\n  editionId     String\n  edition       ShowcaseEdition               @relation(fields: [editionId], references: [id], onDelete: Cascade)\n  boothNumber   String?\n  businessName  String\n  ownerName     String\n  ownerAge      Int?\n  category      String?\n  description   String?\n  status        String                        @default(\"PENDING\")\n  boothSize     String?\n  specialNeeds  String?\n  parentName    String?\n  parentContact String?\n  products      ShowcaseYouthpreneurProduct[]\n  createdAt     DateTime                      @default(now())\n  updatedAt     DateTime                      @updatedAt\n\n  @@index([editionId])\n  @@map(\"showcase_youthpreneur_booth\")\n}\n\nmodel ShowcaseYouthpreneurProduct {\n  id          String                    @id @default(cuid())\n  boothId     String\n  booth       ShowcaseYouthpreneurBooth @relation(fields: [boothId], references: [id], onDelete: Cascade)\n  name        String\n  price       Float?\n  description String?\n  createdAt   DateTime                  @default(now())\n\n  @@index([boothId])\n  @@map(\"showcase_youthpreneur_product\")\n}\n\nmodel ShowcaseWaitlist {\n  id        String          @id @default(cuid())\n  editionId String\n  edition   ShowcaseEdition @relation(fields: [editionId], references: [id], onDelete: Cascade)\n  name      String\n  email     String\n  phone     String?\n  createdAt DateTime        @default(now())\n\n  @@index([editionId])\n  @@map(\"showcase_waitlist\")\n}\n\n// ============================================================\n// RECRUITMENT MODULE (HR)\n// Additive tables for the HR Recruitment kanban. Mirrors the CRM kanban shape\n// but with its own tables and a 29-stage HR pipeline. Recruits are imported\n// from the GHL \"HR Recruitment\" export; a recruit that matches a BranchStaff\n// row added since the cutoff is flagged `hired` and carries `branchStaffId`\n// (stored as a plain id — no FK relation, so the existing BranchStaff model is\n// not modified). Lives in this (portal) DB so the hired-match is a same-DB join.\n// ============================================================\n\nmodel RecStage {\n  id        String   @id @default(uuid())\n  name      String\n  shortCode String   @unique\n  order     Int\n  color     String   @default(\"slate\")\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  recruits    RecRecruit[]\n  historyFrom RecStageHistory[] @relation(\"RecFromStage\")\n  historyTo   RecStageHistory[] @relation(\"RecToStage\")\n\n  @@index([order])\n  @@map(\"rec_stage\")\n}\n\nmodel RecRecruit {\n  id                   String    @id @default(uuid())\n  name                 String\n  email                String?\n  phone                String?\n  source               String?\n  position             String? // \"Working Position Oppo\" from the GHL export\n  branch               String? // branch tag from GHL (e.g. \"st\", \"kd\")\n  stageId              String\n  // Hired-match to BranchStaff (added since the import cutoff). Set by the\n  // import's email/phone/name cross-check; null/false until matched.\n  hired                Boolean   @default(false)\n  branchStaffId        Int?\n  // Provenance from the GHL export so re-imports are idempotent.\n  ghlOpportunityId     String?   @unique\n  ghlContactId         String?\n  ghlCreatedAt         DateTime?\n  // Link to ebright_hrfs.career_applications.id — set when a candidate card is\n  // ingested from a \"Join the Team\" form submission. Unique so the reconcile\n  // never creates a second card for the same application.\n  applicationId        Int?      @unique\n  // ── Training-day attendance workflow ──────────────────────────────────────\n  // When a card enters a training stage (TR1/TR2/TR3) we stamp trainingEnteredAt\n  // and null trainingConfirmedAt. Once 3 days pass without a confirmation, HR is\n  // prompted (dashboard popup) to confirm attendance; confirming stamps\n  // trainingConfirmedAt and (for TR1/TR2) advances to the next training day.\n  trainingEnteredAt    DateTime?\n  trainingConfirmedAt  DateTime?\n  // Set when a training no-show is parked in Reschedule: rescheduleReturnCode is\n  // the training stage to send them back to, rescheduleAt the date to do it on.\n  // A background reconcile moves them back when rescheduleAt arrives.\n  rescheduleAt         DateTime?\n  rescheduleReturnCode String?\n  // Archived cards are hidden from the active board but still viewable via the\n  // \"Show archived\" toggle (and restorable). Distinct from deletedAt: archiving\n  // is for parking leads that aren't backed by a real applications record.\n  archivedAt           DateTime?\n  deletedAt            DateTime?\n  createdAt            DateTime  @default(now())\n  updatedAt            DateTime  @updatedAt\n\n  stage     RecStage          @relation(fields: [stageId], references: [id])\n  history   RecStageHistory[]\n  interview RecInterview?\n  resumes   RecResume[]\n\n  @@index([stageId])\n  @@index([hired])\n  @@index([branchStaffId])\n  @@map(\"rec_recruit\")\n}\n\nmodel RecStageHistory {\n  id          String   @id @default(uuid())\n  recruitId   String\n  fromStageId String?\n  toStageId   String\n  changedBy   String?\n  note        String?\n  changedAt   DateTime @default(now())\n\n  recruit   RecRecruit @relation(fields: [recruitId], references: [id], onDelete: Cascade)\n  fromStage RecStage?  @relation(\"RecFromStage\", fields: [fromStageId], references: [id])\n  toStage   RecStage   @relation(\"RecToStage\", fields: [toStageId], references: [id])\n\n  @@index([recruitId])\n  @@map(\"rec_stage_history\")\n}\n\nmodel RecInterview {\n  id          String   @id @default(uuid())\n  recruitId   String   @unique\n  // Stored naive-KL-as-UTC (the HR picks 03:00 PM and we persist UTC hour 15),\n  // matching the trial-appointment convention elsewhere in the portal so the\n  // Calendar grid reads back via getUTC* without a double timezone shift.\n  scheduledAt DateTime\n  location    String?\n  note        String?\n  createdBy   String?\n  createdAt   DateTime @default(now())\n  updatedAt   DateTime @updatedAt\n\n  recruit RecRecruit @relation(fields: [recruitId], references: [id], onDelete: Cascade)\n\n  @@index([scheduledAt])\n  @@map(\"rec_interview\")\n}\n\nmodel RecResume {\n  id          String   @id @default(uuid())\n  recruitId   String\n  fileName    String\n  mimeType    String   @default(\"application/octet-stream\")\n  sizeBytes   Int      @default(0)\n  // Binary lives in ONE place: the DB (data) for legacy/unconfigured envs, or\n  // Google Drive (driveFileId) once the recruitment Drive folder is set. The\n  // API route streams whichever is present, keeping access auth-gated either way.\n  data        Bytes?\n  driveFileId String?\n  uploadedBy  String?\n  uploadedAt  DateTime @default(now())\n\n  recruit RecRecruit @relation(fields: [recruitId], references: [id], onDelete: Cascade)\n\n  @@index([recruitId])\n  @@index([uploadedAt])\n  @@map(\"rec_resume\")\n}\n"
}

